@@ -0,0 +1,46 @@
+---
+config:
+  flowchart:
+    curve: linear
+---
+graph TD;
+	__start__([<p>__start__</p>]):::first
+	P01(P01)
+	P02(P02)
+	P03(P03)
+	P04(P04)
+	P05(P05)
+	P07(P07)
+	P06(P06)
+	decontaminate(decontaminate)
+	P08(P08)
+	P09(P09)
+	P10(P10)
+	P11(P11)
+	select(select)
+	__end__([<p>__end__</p>]):::last
+	P01 -.-> P02;
+	P01 -.-> __end__;
+	P02 --> P03;
+	P03 -.-> P04;
+	P03 -.-> __end__;
+	P04 --> P05;
+	P05 --> P07;
+	P06 --> decontaminate;
+	P07 -.-> P06;
+	P07 -.-> __end__;
+	P08 --> P09;
+	P09 --> P10;
+	P10 --> P11;
+	P11 --> select;
+	__start__ --> P01;
+	decontaminate -.-> P08;
+	decontaminate -.-> __end__;
+	select -.-> P08;
+	select -.-> __end__;
+	P03 -.-> P03;
+	P07 -.-> P07;
+	classDef default fill:#f2f0ff,line-height:1.2
+	classDef first fill-opacity:0
+	classDef last fill:#bfb6fc
+
